bridges={'men.html':('Одежда в деталях','Посмотрите, как устроены пояс и стопа, или соберите свою подборку образов.','read-construction.html','Стопа, пояс, шортики','lookbook.html?filter=men','Мужские образы'), 'leggings.html':('Продолжить исследование','От посадки и движений — к внимательному чтению характеристик.','read-product-card.html','Читаем карточку изделия','textures.html','Рассмотреть полотно'), 'business.html':('У каждой марки — своя история','Свяжите экономику с людьми, производством и событиями.','read-making.html','От фабрики до витрины','history.html#brand-archive','Архив брендов'), 'guide.html':('Закрепить выбор','Разберите карточку товара и посмотрите на реальные фактуры.','read-product-card.html','Пять вопросов к одной паре','textures.html','Под лупой'), 'nylon.html':('От волокна к впечатлению','Посмотрите, как материал читается на настоящей фотографии.','read-light.html','Свет и блеск','textures.html','Исследовать детали'), 'lookbook.html':('Посмотреть внимательнее','Увеличение, сравнение и истории, которые объясняют фотографию.','textures.html','Открыть под лупой','journal.html','Читать журнал')}
for file,(title,copy,url,label,url2,label2) in bridges.items():
 p=S/file;t=strip(p.read_text(encoding='utf-8'),'experience-related');insert=f'<section class="portal-container experience-related" data-reveal><h2>{title}</h2><p>{copy}</p><a href="{url}">{label} ↗</a><a href="{url2}">{label2} →</a></section>';t=t.replace('</main>','<!-- experience-related -->'+insert+'<!-- /experience-related --></main>');p.write_text(t,encoding='utf-8')

