t=t.replace('<div id="editorial-gallery"', '<!-- experience-gallery --><div class="gallery-personal"><button type="button" data-gallery-filter="saved" aria-pressed="false">Мои фотографии <span id="photo-saved-count">0</span></button><div role="group" aria-label="Размер фотографий"><button type="button" data-gallery-density="standard" aria-pressed="true">Сетка</button><button type="button" data-gallery-density="large" aria-pressed="false">Крупнее</button></div><p class="experience-small">Сохранённое доступно в этом браузере.</p></div><!-- /experience-gallery --><div id="editorial-gallery"',1)
